rawInput.script:
export const meta = {
  name: 'tiny-greet',
  description: 'One Greet phase with two agents (a, b) that each reply with one word',
  phases: [{ title: 'Greet' }],
}
phase('Greet')
const results = await parallel([
  () => agent('Reply with exactly one word (a greeting). Do not use any tools.', { label: 'a', phase: 'Greet' }),
  () => agent('Reply with exactly one word (a greeting). Do not use any tools.', { label: 'b', phase: 'Greet' }),
])
return { a: results[0], b: results[1] }

